// Auth tables (user, session, account, verification) are generated by the Better Auth CLI:
// `bunx @better-auth/cli generate`. Regenerate them when the auth config adds fields.
import { relations, sql } from "drizzle-orm";
import { index, integer, primaryKey, sqliteTable, text } from "drizzle-orm/sqlite-core";

export const user = sqliteTable("user", {
	id: text("id").primaryKey(),
	name: text("name").notNull(),
	email: text("email").notNull().unique(),
	emailVerified: integer("email_verified", { mode: "boolean" }).default(false).notNull(),
	image: text("image"),
	createdAt: integer("created_at", { mode: "timestamp_ms" })
		.default(sql`(cast(unixepoch('subsecond') * 1000 as integer))`)
		.notNull(),
	updatedAt: integer("updated_at", { mode: "timestamp_ms" })
		.default(sql`(cast(unixepoch('subsecond') * 1000 as integer))`)
		.$onUpdate(() => /* @__PURE__ */ new Date())
		.notNull(),
	// GitHub login, lowercased. Owns the scope with the same name.
	username: text("username").unique(),
});

export const session = sqliteTable(
	"session",
	{
		id: text("id").primaryKey(),
		expiresAt: integer("expires_at", { mode: "timestamp_ms" }).notNull(),
		token: text("token").notNull().unique(),
		createdAt: integer("created_at", { mode: "timestamp_ms" })
			.default(sql`(cast(unixepoch('subsecond') * 1000 as integer))`)
			.notNull(),
		updatedAt: integer("updated_at", { mode: "timestamp_ms" })
			.$onUpdate(() => /* @__PURE__ */ new Date())
			.notNull(),
		ipAddress: text("ip_address"),
		userAgent: text("user_agent"),
		userId: text("user_id")
			.notNull()
			.references(() => user.id, { onDelete: "cascade" }),
	},
	(table) => [index("session_userId_idx").on(table.userId)],
);

export const account = sqliteTable(
	"account",
	{
		id: text("id").primaryKey(),
		accountId: text("account_id").notNull(),
		providerId: text("provider_id").notNull(),
		userId: text("user_id")
			.notNull()
			.references(() => user.id, { onDelete: "cascade" }),
		accessToken: text("access_token"),
		refreshToken: text("refresh_token"),
		idToken: text("id_token"),
		accessTokenExpiresAt: integer("access_token_expires_at", {
			mode: "timestamp_ms",
		}),
		refreshTokenExpiresAt: integer("refresh_token_expires_at", {
			mode: "timestamp_ms",
		}),
		scope: text("scope"),
		password: text("password"),
		createdAt: integer("created_at", { mode: "timestamp_ms" })
			.default(sql`(cast(unixepoch('subsecond') * 1000 as integer))`)
			.notNull(),
		updatedAt: integer("updated_at", { mode: "timestamp_ms" })
			.$onUpdate(() => /* @__PURE__ */ new Date())
			.notNull(),
	},
	(table) => [index("account_userId_idx").on(table.userId)],
);

export const verification = sqliteTable(
	"verification",
	{
		id: text("id").primaryKey(),
		identifier: text("identifier").notNull(),
		value: text("value").notNull(),
		expiresAt: integer("expires_at", { mode: "timestamp_ms" }).notNull(),
		createdAt: integer("created_at", { mode: "timestamp_ms" })
			.default(sql`(cast(unixepoch('subsecond') * 1000 as integer))`)
			.notNull(),
		updatedAt: integer("updated_at", { mode: "timestamp_ms" })
			.default(sql`(cast(unixepoch('subsecond') * 1000 as integer))`)
			.$onUpdate(() => /* @__PURE__ */ new Date())
			.notNull(),
	},
	(table) => [index("verification_identifier_idx").on(table.identifier)],
);

export const userRelations = relations(user, ({ many }) => ({
	sessions: many(session),
	accounts: many(account),
}));

export const sessionRelations = relations(session, ({ one }) => ({
	user: one(user, {
		fields: [session.userId],
		references: [user.id],
	}),
}));

export const accountRelations = relations(account, ({ one }) => ({
	user: one(user, {
		fields: [account.userId],
		references: [user.id],
	}),
}));

const createdAt = () =>
	integer("created_at", { mode: "timestamp_ms" })
		.default(sql`(cast(unixepoch('subsecond') * 1000 as integer))`)
		.notNull();

// A scope is the `@name` part of a package name. Every package lives in one.
// A user's GitHub username is their scope; other free names can be claimed as org scopes.
export const scopes = sqliteTable("scopes", {
	name: text("name").primaryKey(), // without the "@"
	ownerId: text("owner_id")
		.notNull()
		.references(() => user.id),
	kind: text("kind", { enum: ["user", "org"] }).notNull(),
	createdAt: createdAt(),
});

export const packages = sqliteTable(
	"packages",
	{
		name: text("name").primaryKey(), // full name, "@scope/pkg"
		scope: text("scope")
			.notNull()
			.references(() => scopes.name),
		description: text("description"),
		readme: text("readme"),
		createdAt: createdAt(),
		updatedAt: integer("updated_at", { mode: "timestamp_ms" })
			.default(sql`(cast(unixepoch('subsecond') * 1000 as integer))`)
			.$onUpdate(() => new Date())
			.notNull(),
		// Set when an admin takes the whole package down. Its rows stay, so nobody can publish its
		// name or versions again, but the registry and the website stop serving it.
		takenDownAt: integer("taken_down_at", { mode: "timestamp_ms" }),
		takenDownBy: text("taken_down_by").references(() => user.id),
	},
	(table) => [index("packages_scope_idx").on(table.scope)],
);

// One row per published version. Versions are immutable once written.
export const versions = sqliteTable(
	"versions",
	{
		packageName: text("package_name")
			.notNull()
			.references(() => packages.name),
		version: text("version").notNull(),
		// The version manifest exactly as published, minus `dist.tarball`: tarball URLs are
		// built from the request's origin so the registry works on any domain it is served from.
		manifest: text("manifest", { mode: "json" }).notNull(),
		tarballKey: text("tarball_key").notNull(), // R2 object key
		integrity: text("integrity").notNull(), // "sha512-<base64>"
		shasum: text("shasum").notNull(), // sha1 hex
		size: integer("size").notNull(), // tarball bytes
		publishedBy: text("published_by")
			.notNull()
			.references(() => user.id),
		publishedAt: createdAt(),
		// Set when an admin takes this version down. The row stays so the version number can never be
		// published again; the packument leaves it out and its tarball is no longer served.
		takenDownAt: integer("taken_down_at", { mode: "timestamp_ms" }),
		takenDownBy: text("taken_down_by").references(() => user.id),
	},
	(table) => [primaryKey({ columns: [table.packageName, table.version] })],
);

export const distTags = sqliteTable(
	"dist_tags",
	{
		packageName: text("package_name")
			.notNull()
			.references(() => packages.name),
		tag: text("tag").notNull(),
		version: text("version").notNull(),
	},
	(table) => [primaryKey({ columns: [table.packageName, table.tag] })],
);

// Publish tokens for npm clients. Only the SHA-256 of the token is stored.
export const tokens = sqliteTable(
	"tokens",
	{
		id: text("id").primaryKey(),
		userId: text("user_id")
			.notNull()
			.references(() => user.id, { onDelete: "cascade" }),
		name: text("name").notNull(),
		tokenHash: text("token_hash").notNull().unique(),
		createdAt: createdAt(),
		lastUsedAt: integer("last_used_at", { mode: "timestamp_ms" }),
	},
	(table) => [index("tokens_userId_idx").on(table.userId)],
);

// Tarball downloads per package per UTC day ("2026-10-22").
export const downloads = sqliteTable(
	"downloads",
	{
		packageName: text("package_name")
			.notNull()
			.references(() => packages.name),
		day: text("day").notNull(),
		count: integer("count").notNull().default(0),
	},
	(table) => [primaryKey({ columns: [table.packageName, table.day] })],
);

// Reports from the Report form on package pages, for an admin (ADMIN_LOGINS) to act on.
export const reports = sqliteTable(
	"reports",
	{
		id: text("id").primaryKey(),
		packageName: text("package_name")
			.notNull()
			.references(() => packages.name),
		version: text("version"), // null: the report is about the whole package
		reason: text("reason", { enum: ["malware", "spam", "impersonation", "legal", "other"] }).notNull(),
		details: text("details").notNull(),
		// Null when the reporter wasn't signed in.
		reporterId: text("reporter_id").references(() => user.id, { onDelete: "set null" }),
		status: text("status", { enum: ["open", "removed", "dismissed"] })
			.notNull()
			.default("open"),
		createdAt: createdAt(),
		resolvedAt: integer("resolved_at", { mode: "timestamp_ms" }),
		resolvedBy: text("resolved_by").references(() => user.id),
	},
	(table) => [index("reports_status_idx").on(table.status)],
);

// Fixed-window counters for the rate limits in src/lib/rate-limit.ts. One row per action and
// subject ("publish:user:<id>", "sign-in:ip:<hash>"); a row older than a day is stale and deleted.
export const rateLimits = sqliteTable(
	"rate_limits",
	{
		key: text("key").primaryKey(),
		windowStart: integer("window_start").notNull(), // ms since the epoch
		count: integer("count").notNull(),
	},
	(table) => [index("rate_limits_window_start_idx").on(table.windowStart)],
);
